from typing import List
from wordle.types import GuessResult, Feedback


def render_board(results: List[GuessResult]) -> str:
    """Render the entire game board with all guesses.\n\n    Args:\n        results: List of all guess results so far\n\n    Returns:\n        Formatted string representation of the board\n    """
    board = ''
    for result in results:
        board += render_guess(result) + '\n'
    for _ in range(6 - len(results)):
        board += render_empty_row() + '\n'
    return board


def render_guess(result: GuessResult) -> str:
    """Render a single guess result as a colored row.\n\n    Args:\n        result: The guess result to render\n\n    Returns:\n        Formatted string representation of the guess\n    """
    row = ''
    for letter, feedback in zip(result.guess, result.feedbacks):
        row += _colorize_letter(letter, feedback.value) + ' '
    return row


def render_empty_row() -> str:
    """Render an empty row for unused attempts.\n\n    Returns:\n        Formatted string representation of an empty row\n    """
    return ' ' * 30


def _colorize_letter(letter: str, feedback_type: str) -> str:
    """Apply color formatting to a letter based on feedback.\n\n    Args:\n        letter: The letter to colorize\n        feedback_type: The feedback type ('hit', 'present', 'miss')\n\n    Returns:\n        Colored letter with ANSI codes\n    """
    color_map = {
        'hit': '\033[92m',
        'present': '\033[93m',
        'miss': '\033[90m'
    }
    end_color = '\033[0m'
    return color_map[feedback_type] + letter + end_color


def render_keyboard(used_letters: dict[str, str]) -> str:
    """Render a keyboard showing letter status.\n\n    Args:\n        used_letters: Map of letters to their feedback status\n\n    Returns:\n        Formatted keyboard display\n    """
    keyboard = ''
    for letter in 'QWERTYUIOPASDFGHJKLZXCVBNM':
        if letter in used_letters:
            keyboard += _colorize_letter(letter, used_letters[letter]) + ' '
        else:
            keyboard += letter + ' '
    return keyboard
